<script setup>
import { computed, inject, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import AppIcon from '../components/AppIcon.vue'
import TaskCard from '../components/TaskCard.vue'
import { useWorkspace } from '../composables/useWorkspace'
import { filterTasks } from '../lib/tasks'
const route = useRoute()
const { user, tasks, stats, loading, error, loadTasks } = useWorkspace()
const openEditor = inject('taskEditor')
const query = inject('searchQuery')
const status = ref('all')
const sort = ref('newest')
const view = ref(localStorage.getItem('flow.view') === 'board' ? 'board' : 'list')
const page = ref(1)
const overview = computed(() => route.name === 'overview')
const completedPage = computed(() => route.name === 'completed')
const filtered = computed(() => filterTasks(tasks.value, { query: query.value, status: completedPage.value ? 'completed' : status.value, sort: sort.value }))
const pageSize = computed(() => overview.value ? 5 : 10)
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize.value)))
const visible = computed(() => filtered.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value))
const focusTask = computed(() => tasks.value.find((task) => !task.completed))
const date = new Intl.DateTimeFormat('ru-RU', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date())
const greeting = new Date().getHours() < 12 ? 'Доброе утро' : new Date().getHours() < 18 ? 'Добрый день' : 'Добрый вечер'
const week = computed(() => Array.from({ length: 7 }, (_, index) => {
  const day = new Date()
  day.setDate(day.getDate() - 6 + index)
  const count = tasks.value.filter((task) => task.completed && new Date(task.updated_at).toDateString() === day.toDateString()).length
  return { label: new Intl.DateTimeFormat('ru-RU', { weekday: 'short' }).format(day), count, today: index === 6 }
}))
const weekMax = computed(() => Math.max(1, ...week.value.map((day) => day.count)))
const weekTotal = computed(() => week.value.reduce((sum, day) => sum + day.count, 0))
watch([query, status, sort, () => route.name], () => { page.value = 1 })
watch(pages, (value) => { page.value = Math.min(page.value, value) })
watch(view, (value) => { try { localStorage.setItem('flow.view', value) } catch { /* View is usable without persistence. */ } })
</script>

<template>
  <div class="workspace-view">
    <div class="page-heading"><div><p class="page-eyebrow">{{ overview ? date : completedPage ? 'КАЖДЫЙ ШАГ ИМЕЕТ ЗНАЧЕНИЕ' : 'ОТ ИДЕИ К РЕЗУЛЬТАТУ' }}</p><h1>{{ overview ? `${greeting}, ${user.first_name || user.username}` : completedPage ? 'Ваши маленькие победы' : 'Мои задачи' }}<span v-if="overview" class="greeting-sun"><AppIcon name="sun" :size="28" /></span><span v-else class="green-text">.</span></h1><p class="muted">{{ overview ? 'Хороший день, чтобы сделать что-то важное.' : completedPage ? 'Посмотрите, сколько всего уже получилось.' : 'Всё, что важно. В одном месте, в вашем ритме.' }}</p></div><button class="button primary" @click="openEditor()"><AppIcon name="plus" :size="18" />Новая задача</button></div>
    <template v-if="overview">
      <section class="welcome-banner"><div><span class="eyebrow"><AppIcon name="sparkles" :size="15" />ВАШ ФОКУС НА СЕГОДНЯ</span><h2>Большие дела.<br><span>По одному шагу.</span></h2><p>{{ stats.active ? `Сейчас в работе: ${stats.active}. Выберите одну задачу и начните с неё.` : 'Свободное пространство для новых идей. С чего начнём?' }}</p><button class="banner-link" @click="focusTask ? openEditor(focusTask) : openEditor()">{{ focusTask ? 'Выбрать следующий шаг' : 'Добавить первую задачу' }}<AppIcon name="arrow" :size="17" /></button></div><div class="banner-art" aria-hidden="true"><div class="banner-orbit"></div><div class="banner-orbit second"></div><div class="plant-stem"></div><i class="plant-leaf plant-a"></i><i class="plant-leaf plant-b"></i><i class="plant-leaf plant-c"></i><i class="plant-leaf plant-d"></i><div class="plant-pot"></div><div class="mini-check"><AppIcon name="check" :size="21" /></div><span class="banner-star">✦</span><span class="banner-dot"></span></div><div class="banner-progress"><span class="progress-ring" :style="{ '--progress': stats.percent + '%' }"><span>{{ stats.percent }}<small>%</small></span></span><span>ваших задач<br>уже завершено</span></div></section>
      <section class="stats-grid" aria-label="Статистика задач"><article class="stat-card"><div><span>Всего задач</span><strong>{{ loading ? '—' : stats.total }}</strong><small>Всё под контролем</small></div><span class="stat-icon lavender"><AppIcon name="tasks" :size="22" /></span></article><article class="stat-card"><div><span>В работе</span><strong>{{ loading ? '—' : stats.active }}</strong><small><span class="tiny-dot amber-dot"></span>Шаг за шагом к цели</small></div><span class="stat-icon cream"><AppIcon name="clock" :size="22" /></span></article><article class="stat-card"><div><span>Завершено</span><strong>{{ loading ? '—' : stats.completed }}</strong><small><span class="tiny-dot green-dot"></span>Повод гордиться собой</small></div><span class="stat-icon mint"><AppIcon name="circle" :size="22" /></span></article><article class="stat-card"><div><span>Ваш прогресс</span><strong>{{ loading ? '—' : stats.percent }}<em v-if="!loading">%</em></strong><small>Каждое дело имеет значение</small></div><span class="stat-icon rose"><AppIcon name="trend" :size="22" /></span></article></section>
    </template>
    <div class="dashboard-grid" :class="{ 'full-width': !overview }"><section class="tasks-panel panel"><div class="section-heading"><div><h2>{{ overview ? 'Ваши задачи' : completedPage ? 'Завершённые задачи' : 'Все задачи' }} <span class="count-badge">{{ filtered.length }}</span></h2><p v-if="overview" class="muted">Меньше откладывать, больше делать.</p></div><RouterLink v-if="overview" to="/tasks" class="text-link">Все задачи<AppIcon name="arrow" :size="16" /></RouterLink><div v-else class="view-toggle" aria-label="Представление задач"><button :class="{ selected: view === 'list' }" :aria-pressed="view === 'list'" aria-label="Список" @click="view = 'list'"><AppIcon name="list" :size="18" /></button><button :class="{ selected: view === 'board' }" :aria-pressed="view === 'board'" aria-label="Доска" @click="view = 'board'"><AppIcon name="board" :size="18" /></button></div></div>
      <div class="task-toolbar"><div v-if="!completedPage" class="task-tabs" role="group" aria-label="Статус задач"><button v-for="tab in [{ key: 'all', label: 'Все', count: stats.total }, { key: 'active', label: 'В работе', count: stats.active }, { key: 'completed', label: 'Готово', count: stats.completed }]" :key="tab.key" :class="{ active: status === tab.key }" :aria-pressed="status === tab.key" @click="status = tab.key">{{ tab.label }}<span>{{ tab.count }}</span></button></div><span v-else class="muted small-text">Освободили место для нового</span><label class="sort-select"><AppIcon name="sliders" :size="15" /><select v-model="sort" aria-label="Сортировка задач"><option value="newest">Сначала новые</option><option value="oldest">Сначала старые</option><option value="title">По названию</option></select></label></div>
      <div v-if="query" class="search-summary"><span>Поиск: «{{ query }}» · Найдено: {{ filtered.length }}</span><button class="text-link" @click="query = ''">Сбросить</button></div>
      <div v-if="loading" class="loading-state" role="status"><div v-for="n in 4" :key="n" class="skeleton-row"><span></span><div><i></i><i></i></div></div><span class="sr-only">Загружаем задачи…</span></div>
      <div v-else-if="error" class="empty-state" role="alert"><span class="empty-icon"><AppIcon name="refresh" :size="28" /></span><h3>Не удалось загрузить задачи</h3><p>{{ error }}</p><button class="button secondary" @click="loadTasks">Попробовать снова</button></div>
      <div v-else-if="!filtered.length" class="empty-state"><span class="empty-icon"><AppIcon :name="query ? 'search' : completedPage ? 'circle' : 'leaf'" :size="30" /></span><h3>{{ query ? 'Пока ничего не нашлось' : completedPage ? 'Здесь будут ваши победы' : status === 'active' ? 'Всё сделано. Можно выдохнуть!' : status === 'completed' ? 'Всё ещё впереди' : 'Дайте планам место' }}</h3><p>{{ query ? 'Попробуйте другое слово или сбросьте фильтры.' : completedPage || status === 'completed' ? 'Завершите первую задачу — и она появится здесь.' : 'Добавьте задачу и сделайте первый шаг к своей цели.' }}</p><button v-if="query || status !== 'all'" class="button secondary" @click="query = ''; status = 'all'">Сбросить фильтры</button><button v-else-if="!completedPage" class="button primary" @click="openEditor()"><AppIcon name="plus" :size="16" />Создать задачу</button></div>
      <template v-else><div v-if="view === 'board' && !overview" class="board-grid"><section v-for="column in [{ done: false, label: 'В работе' }, { done: true, label: 'Завершено' }]" :key="String(column.done)" class="board-column"><h3><span class="tiny-dot" :class="column.done ? 'green-dot' : 'amber-dot'"></span>{{ column.label }}<span>{{ visible.filter(t => t.completed === column.done).length }}</span></h3><TaskCard v-for="task in visible.filter(t => t.completed === column.done)" :key="task.id" :task="task" board @edit="openEditor" @delete="openEditor($event, 'delete')" /><p v-if="!visible.some(t => t.completed === column.done)" class="board-empty">На этой странице задач нет</p></section></div><div v-else class="task-list"><TaskCard v-for="task in visible" :key="task.id" :task="task" @edit="openEditor" @delete="openEditor($event, 'delete')" /></div></template>
      <div v-if="!loading && !error" class="task-panel-footer"><button class="add-task-link" @click="openEditor()"><AppIcon name="plus" :size="17" />Добавить задачу</button><div v-if="pages > 1" class="pagination"><span>{{ page }} / {{ pages }}</span><button class="icon-button previous" :disabled="page === 1" aria-label="Предыдущая страница" @click="page--"><AppIcon name="chevron" :size="16" /></button><button class="icon-button" :disabled="page === pages" aria-label="Следующая страница" @click="page++"><AppIcon name="chevron" :size="16" /></button></div><span v-else class="small-text muted">{{ filtered.length ? `Показано ${visible.length} из ${filtered.length}` : 'Начните с малого' }}</span></div>
    </section>
    <aside v-if="overview" class="insights-column"><section class="panel activity-panel"><div class="section-heading"><h2>Ваш ритм</h2><span class="icon-tile small"><AppIcon name="trend" :size="17" /></span></div><div class="activity-number">{{ weekTotal }}<span>завершено за 7 дней</span></div><div class="week-chart" role="img" :aria-label="week.map(day => `${day.label}: ${day.count}`).join(', ')"><div v-for="day in week" :key="day.label" class="chart-day" :class="{ today: day.today }"><span class="bar-track"><span class="bar-value" :style="{ height: `${Math.max(day.count ? 12 : 3, day.count / weekMax * 100)}%` }" :title="`${day.label}: ${day.count}`"><span v-if="day.count">{{ day.count }}</span></span></span><small>{{ day.label }}</small></div></div><p class="chart-caption"><span class="tiny-dot green-dot"></span>Завершённые по дате изменения</p></section><section class="focus-card"><span class="focus-label"><AppIcon name="leaf" :size="17" />НЕМНОГО ЗАБОТЫ О СЕБЕ</span><h3>Продуктивность —<br>это ещё и паузы.</h3><p>Отвлекитесь от экрана, сделайте вдох и дайте мыслям немного пространства.</p><span class="focus-line"></span><span class="focus-footnote">Вы движетесь в своём темпе. Это нормально.</span><AppIcon class="focus-leaf" name="leaf" :size="100" /></section></aside></div>
  </div>
</template>
